-- Create "hooks_rollout_pins" table
CREATE TABLE "hooks_rollout_pins" (
  "id" uuid NOT NULL DEFAULT generate_uuidv7(),
  "seq" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "organization_id" text NULL,
  "version" integer NULL,
  "set_by" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
  "updated_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY ("id"),
  CONSTRAINT "hooks_rollout_pins_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization_metadata" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "hooks_rollout_pins_default_version_check" CHECK ((organization_id IS NOT NULL) OR (version IS NOT NULL)),
  CONSTRAINT "hooks_rollout_pins_set_by_check" CHECK (set_by <> ''::text),
  CONSTRAINT "hooks_rollout_pins_version_check" CHECK (version > 0)
);
-- Create index "hooks_rollout_pins_organization_id_seq_idx" to table: "hooks_rollout_pins"
CREATE INDEX "hooks_rollout_pins_organization_id_seq_idx" ON "hooks_rollout_pins" ("organization_id", "seq" DESC);
-- Create index "hooks_rollout_pins_seq_key" to table: "hooks_rollout_pins"
CREATE UNIQUE INDEX "hooks_rollout_pins_seq_key" ON "hooks_rollout_pins" ("seq");
